"""Loop-sensor processing for a single toll gantry lane."""

import time
from dataclasses import dataclass


LOOP_SPACING_M = 6.0
CENTS_PER_DOLLAR = 100

VEHICLE_CLASSES = {
    2: "car",
    3: "light_truck",
    5: "heavy_truck",
    6: "bus",
}


@dataclass
class LoopEvent:
    loop_a_ms: int
    loop_b_ms: int
    axle_count: int
    gross_weight_kg: float


def compute_speed_kph(event: LoopEvent) -> float:
    dt_s = (event.loop_b_ms - event.loop_a_ms) / 1000.0
    if dt_s <= 0:
        raise ValueError("non-positive transit time between loops")
    speed_mps = LOOP_SPACING_M / dt_s
    return speed_mps * 3.6


def classify_vehicle(event: LoopEvent) -> str:
    return VEHICLE_CLASSES.get(event.axle_count, "unclassified")


def gross_weight_lbs(event: LoopEvent) -> float:
    return event.gross_weight_kg * 2.20462


def cents_to_dollars(amount_cents: int) -> float:
    return amount_cents / CENTS_PER_DOLLAR


def minutes_since_midnight(epoch_ms: int) -> int:
    local = time.localtime(epoch_ms / 1000.0)
    return local.tm_hour * 60 + local.tm_min


class GantryWindow:
    """Rolling count of vehicles crossing a gantry within a fixed sampling window."""

    def __init__(self, window_seconds: int = 300):
        self.window_seconds = window_seconds
        self._timestamps_ms = []

    def record(self, epoch_ms: int) -> None:
        self._timestamps_ms.append(epoch_ms)
        cutoff = epoch_ms - self.window_seconds * 1000
        self._timestamps_ms = [t for t in self._timestamps_ms if t >= cutoff]

    def count(self) -> int:
        return len(self._timestamps_ms)

"""Dynamic toll pricing for a gantry lane, combining class rates with a congestion surcharge."""

from gantry_sensors import (
    LoopEvent,
    GantryWindow,
    compute_speed_kph,
    classify_vehicle,
    gross_weight_lbs,
    cents_to_dollars,
    minutes_since_midnight,
)

BASE_RATE_CENTS = {
    "car": 250,
    "light_truck": 400,
    "heavy_truck": 900,
    "bus": 600,
}

OVERWEIGHT_LIMIT_LBS = 26000
OVERWEIGHT_SURCHARGE_CENTS = 500

PEAK_WINDOWS = [(6 * 60, 9 * 60 + 30), (16 * 60, 18 * 60 + 30)]
PEAK_SURCHARGE_FRACTION = 0.20

# lane throughput this gantry is rated for, vehicles/hour
RATED_CAPACITY_VPH = 1800


def is_peak(epoch_ms: int) -> bool:
    minute = minutes_since_midnight(epoch_ms)
    return any(start <= minute <= end for start, end in PEAK_WINDOWS)


def congestion_multiplier(window: GantryWindow) -> float:
    observed = window.count()
    utilization = observed / RATED_CAPACITY_VPH
    if utilization <= 1.0:
        return 1.0
    return 1.0 + min(utilization - 1.0, 1.0)


def compute_toll_cents(event: LoopEvent, window: GantryWindow, epoch_ms: int) -> int:
    vehicle_class = classify_vehicle(event)
    base = BASE_RATE_CENTS.get(vehicle_class, BASE_RATE_CENTS["car"])

    total = float(base)

    if gross_weight_lbs(event) > OVERWEIGHT_LIMIT_LBS:
        total += OVERWEIGHT_SURCHARGE_CENTS

    if is_peak(epoch_ms):
        total *= 1 + PEAK_SURCHARGE_FRACTION

    total *= congestion_multiplier(window)

    speed_kph = compute_speed_kph(event)
    if speed_kph < 15:
        total *= 1.10

    return round(total)


def toll_dollars(event: LoopEvent, window: GantryWindow, epoch_ms: int) -> float:
    return cents_to_dollars(compute_toll_cents(event, window, epoch_ms))


def process_crossing(event: LoopEvent, window: GantryWindow, epoch_ms: int) -> float:
    window.record(epoch_ms)
    return toll_dollars(event, window, epoch_ms)
